            }
            int elem_offset = i * N + tj;
            memcpy_wide_bus_write_double(A, row_tile, (long)elem_offset * sizeof(double), chunk * sizeof(double));
        }
    }

    // Write x and y back to global memory using tiled bursts.
    for (t = 0; t < n; t += TILE) {
        int chunk = (t + TILE <= n) ? TILE : (n - t);
        double x_tile[TILE];
        double y_tile[TILE];
#pragma HLS ARRAY_PARTITION variable=x_tile cyclic factor=8
#pragma HLS ARRAY_PARTITION variable=y_tile cyclic factor=8
        for (j = 0; j < chunk; j++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=1 max=256
            x_tile[j] = x_local[t + j];
            y_tile[j] = y_local[t + j];
        }
        memcpy_wide_bus_write_double(x, x_tile, (long)t * sizeof(double), chunk * sizeof(double));
        memcpy_wide_bus_write_double(y, y_tile, (long)t * sizeof(double), chunk * sizeof(double));
    }
}
}
